const std = @import("std");

pub fn main() !void {
    const nums = [_]i32{ 10, 20, 30, 40, 50 };
    var sum: i32 = 0;

    for (nums) |n| {
        sum += n;
    }

    const avg = @as(f64, @intCast(sum)) / @as(f64, nums.len);

    std.debug.print("Sum: {}\n", .{sum});
    std.debug.print("Average: {d:.1}\n", .{avg});
}
